(()=>{
  // nutrition-ui.js historically rebuilt a menu from the weekday for custom profiles.
  // That made Monday (and the other weekdays) repeat across every displayed week.
  // The training data already carries the 30-week rotation generated by nutrition-variety.js,
  // so expose that rotation to the renderer before each nutrition render.
  function apply(){
    const weeks=window.APP_DATA?.weeks;
    const rotations=window.R42_MENU_ROTATIONS;
    if(!weeks||!rotations)return;
    weeks.forEach((w,wi)=>w.days?.forEach((d,di)=>{
      const code=rotations[wi%rotations.length]?.[di];
      if(code)d.menu=code;
    }));
  }
  apply();
  document.addEventListener('click',e=>{
    if(e.target?.closest?.('nav button[data-v="nutrition"]'))apply();
  },true);
  window.R42_WEEK_MENU_FIX={apply};
})();